import battle_simulator
import random

monster_a = {
    "id": "m_aqualisk",
    "name": "Aqualisk",
    "element": "aqua",
    "moves": ['tidal_crush', 'aqua_jet', 'focus', 'mend']
}

def get_random_opponent():
    elem = random.choice(["pyro", "flora", "aqua", "gale", "volt", "terra"])
    if elem == "pyro":
        moves = ["ember", "pyroclasm", "mend", "bulwark"]
    elif elem == "flora":
        moves = ["vine_lash", "bloom_burst", "mend", "bulwark"]
    elif elem == "aqua":
        moves = ["aqua_jet", "tidal_crush", "mend", "bulwark"]
    elif elem == "gale":
        moves = ["gust", "cyclone", "mend", "bulwark"]
    elif elem == "volt":
        moves = ["spark", "thunderclap", "mend", "bulwark"]
    else:  # terra
        moves = ["pebble", "landslide", "mend", "bulwark"]

    monster_b = {
        "id": "m_random",
        "name": f"Random Opponent ({elem})",
        "element": elem,
        "moves": moves
    }

    strategy_b = {
        "opening_move": random.choice(moves),
        "move_weights": {m: round(random.uniform(0.1, 1.0), 2) for m in moves},
        "switch_to_defense_below": round(random.uniform(0.1, 0.4), 2),
        "defense_move": "mend" if "mend" in moves else moves[0],
        "aggression": round(random.uniform(0.3, 0.9), 2),
        "prefer_super_effective": True
    }
    return monster_b, strategy_b

def test_strat(strategy_a, seed=1234):
    random.seed(seed)
    wins = 0
    trials = 10
    for i in range(trials):
        monster_b, strategy_b = get_random_opponent()
        winner = battle_simulator.simulate_battle(monster_a, strategy_a, monster_b, strategy_b)
        if winner == "a":
            wins += 1
    return wins

strat1 = {
    "opening_move": "tidal_crush",
    "move_weights": {
        "tidal_crush": 1.0,
        "aqua_jet": 0.5,
        "focus": 0.3,
        "mend": 0.15
    },
    "switch_to_defense_below": 0.35,
    "defense_move": "mend",
    "aggression": 0.9,
    "prefer_super_effective": True
}

strat2 = {
    "opening_move": "focus",
    "move_weights": {
        "tidal_crush": 1.0,
        "aqua_jet": 0.5,
        "focus": 0.3,
        "mend": 0.15
    },
    "switch_to_defense_below": 0.35,
    "defense_move": "mend",
    "aggression": 0.9,
    "prefer_super_effective": True
}

strat3 = {
    "opening_move": None,
    "move_weights": {
        "tidal_crush": 1.0,
        "aqua_jet": 0.5,
        "focus": 0.3,
        "mend": 0.15
    },
    "switch_to_defense_below": 0.35,
    "defense_move": "mend",
    "aggression": 0.9,
    "prefer_super_effective": True
}

print("Wins with tidal_crush opening:", test_strat(strat1))
print("Wins with focus opening:", test_strat(strat2))
print("Wins with No opening (let scoring choose):", test_strat(strat3))
